# owner: platform
import unittest

from hourglass.rounding import label_rounded_spans
from hourglass.models import Span


class LabelRoundedTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        self.assertEqual(
            label_rounded_spans([Span(544, 1034)], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_exact_half_rounds_up(self):
        self.assertEqual(
            label_rounded_spans([Span(548, 600)], 15), ["09:15-10:00 (0h 45m)"]
        )

    def test_each_span_labelled_in_order(self):
        spans = [Span(60, 125), Span(600, 610)]
        self.assertEqual(
            label_rounded_spans(spans, 15),
            ["01:00-02:00 (1h 0m)", "10:00-10:15 (0h 15m)"],
        )

    def test_empty(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_divisors_of_an_hour_are_accepted(self):
        for step in (1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(len(label_rounded_spans([Span(0, 60)], step)), 1)

    def test_rejects_steps_that_do_not_divide_an_hour(self):
        for step in (0, -15, 7, 25, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans([Span(540, 600)], step)

    def test_span_that_collapses_is_rejected(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([Span(541, 544)], 15)
